async function loadSalesReports(filters = {}) {
  const params = new URLSearchParams(); if (filters.date_from) params.set('date_from', filters.date_from); if (filters.date_to) params.set('date_to', filters.date_to); if (filters.customer_id) params.set('customer_id', filters.customer_id);
  const data = await api(`/sales/reports${params.toString() ? `?${params}` : ''}`);
  const money = value => `S/ ${Number(value || 0).toLocaleString('es-PE', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  const statusLabels = { approved: 'Aprobadas', in_progress: 'En ejecución', completed: 'Completadas', cancelled: 'Canceladas' };
  const visitStatusLabels = { planned: 'Programadas', completed: 'Realizadas', cancelled: 'Canceladas' };
  const maxCustomer = Math.max(...data.customers.map(row => Number(row.total)), 1);
  const customerBars = data.customers.map((row, index) => `<div class="report-bar-row"><div class="report-bar-head"><div class="report-bar-title"><span class="report-bar-rank">${index + 1}</span>${htmlEscape(row.label)}<small class="report-bar-meta">${row.quotations} cotización${row.quotations === 1 ? '' : 'es'} · Participación ${((Number(row.total) / Math.max(Number(data.totals.total), 1)) * 100).toFixed(1)}%</small></div><strong class="report-bar-value">${money(row.total)}</strong></div><div class="report-bar-track"><span style="width:${Math.max(3, Number(row.total) / maxCustomer * 100)}%"></span></div></div>`).join('');
  const conversionMax = Math.max(data.conversion.total, 1);
  const conversionBars = `<div class="report-bar-row"><div class="report-bar-head"><div class="report-bar-title">Convertidas en orden<small class="report-bar-meta">Cotizaciones con orden de servicio asociada</small></div><strong class="report-bar-value">${data.conversion.converted} · ${Number(data.conversion.rate).toFixed(1)}%</strong></div><div class="report-bar-track blue"><span style="width:${data.conversion.converted / conversionMax * 100}%"></span></div></div><div class="report-bar-row"><div class="report-bar-head"><div class="report-bar-title">En evaluación<small class="report-bar-meta">Cotizaciones que aún no se convierten en orden</small></div><strong class="report-bar-value">${data.conversion.pending}</strong></div><div class="report-bar-track amber"><span style="width:${data.conversion.pending / conversionMax * 100}%"></span></div></div>`;
  const orderMax = Math.max(...data.order_statuses.map(row => Number(row.value)), 1);
  const orderBars = data.order_statuses.map(row => `<div class="report-bar-row"><div class="report-bar-head"><div class="report-bar-title">${statusLabels[row.status] || row.status}<small class="report-bar-meta">Órdenes de servicio</small></div><strong class="report-bar-value">${row.value}</strong></div><div class="report-bar-track purple"><span style="width:${Math.max(3, Number(row.value) / orderMax * 100)}%"></span></div></div>`).join('');
  const visitMax = Math.max(...data.visit_statuses.map(row => Number(row.value)), 1);
  const visitBars = data.visit_statuses.map(row => `<div class="report-bar-row"><div class="report-bar-head"><div class="report-bar-title">${visitStatusLabels[row.status] || row.status}<small class="report-bar-meta">Visitas técnicas</small></div><strong class="report-bar-value">${row.value}</strong></div><div class="report-bar-track amber"><span style="width:${Math.max(3, Number(row.value) / visitMax * 100)}%"></span></div></div>`).join('');
  const history = data.monthly.map(row => ({ label: row.period, value: Number(row.total) })); const lastValues = history.slice(-3).map(row => row.value); const average = lastValues.length ? lastValues.reduce((sum, value) => sum + value, 0) / lastValues.length : 0; const trend = history.length > 1 ? (history[history.length - 1].value - history[0].value) / (history.length - 1) : 0; const forecast = [1, 2, 3].map(step => Math.max(0, (history.at(-1)?.value || average) + trend * step)); const chartValues = [...history.map(row => row.value), ...forecast]; const chartMax = Math.max(...chartValues, 1); const chartWidth = 720; const chartHeight = 230; const chartLeft = 42; const chartRight = 16; const chartTop = 18; const chartBottom = 38; const xStep = (chartWidth - chartLeft - chartRight) / Math.max(chartValues.length - 1, 1); const point = (value, index) => `${(chartLeft + index * xStep).toFixed(1)},${(chartTop + (chartHeight - chartTop - chartBottom) * (1 - value / chartMax)).toFixed(1)}`; const historyPoints = history.map((row, index) => point(row.value, index)).join(' '); const forecastPoints = [history.at(-1)?.value || 0, ...forecast].map((value, index) => point(value, Math.max(history.length - 1, 0) + index)).join(' '); const lineLabels = [...history.map(row => row.label), 'F+1', 'F+2', 'F+3'];
  const lineChart = `<div class="line-chart-wrap"><svg viewBox="0 0 ${chartWidth} ${chartHeight}" role="img" aria-label="Valor cotizado mensual y proyección"><line x1="${chartLeft}" y1="${chartTop}" x2="${chartLeft}" y2="${chartHeight - chartBottom}" stroke="#dbe5e8"/><line x1="${chartLeft}" y1="${chartHeight - chartBottom}" x2="${chartWidth - chartRight}" y2="${chartHeight - chartBottom}" stroke="#dbe5e8"/><polyline points="${historyPoints || point(0, 0)}" fill="none" stroke="#3478b9" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><polyline points="${forecastPoints}" fill="none" stroke="#f0a83b" stroke-width="4" stroke-dasharray="8 6" stroke-linecap="round" stroke-linejoin="round"/>${chartValues.map((value, index) => `<circle cx="${point(value, index).split(',')[0]}" cy="${point(value, index).split(',')[1]}" r="4" fill="${index < history.length ? '#3478b9' : '#f0a83b'}"/>`).join('')} ${lineLabels.map((label, index) => `<text x="${chartLeft + index * xStep}" y="${chartHeight - 12}" text-anchor="middle" font-size="10" fill="#64727d">${htmlEscape(label)}</text>`).join('')}</svg><div class="chart-legend"><span><i class="legend-dot blue"></i>Histórico</span><span><i class="legend-dot forecast"></i>Forecast lineal</span></div></div>`;
  $('#workspace-content').innerHTML = `${salesNav('reports')}<section class="hero"><div><p class="eyebrow">MÓDULO VENTAS / ANALÍTICA</p><h2>Reportes comerciales</h2><p>Lectura ejecutiva del embudo comercial, clientes, órdenes de servicio y visitas técnicas.</p></div><span class="hero-badge">● Datos reales</span></section><section class="module-card report-filter-card"><div class="section-heading"><div><h3>Filtros del análisis</h3><p class="muted">Aplica el rango y cliente a los indicadores comerciales.</p></div></div><div class="directory-filters"><label>Desde<input id="sales-report-date-from" type="date" value="${htmlEscape(filters.date_from || '')}"></label><label>Hasta<input id="sales-report-date-to" type="date" value="${htmlEscape(filters.date_to || '')}"></label><label>Cliente<select id="sales-report-customer"><option value="">Todos los clientes</option>${data.customer_options.map(customer => `<option value="${customer.id}" ${String(filters.customer_id || '') === String(customer.id) ? 'selected' : ''}>${htmlEscape(customer.name)}</option>`).join('')}</select></label><button class="primary" id="sales-report-apply" type="button">Aplicar filtros</button><button class="link-button filter-clear" id="sales-report-clear" type="button">Limpiar</button></div></section><div class="kpi-grid report-kpi-band"><article class="metric-card teal"><small>Clientes activos</small><strong>${data.totals.customers}</strong><span class="kpi-note">Directorio vigente</span></article><article class="metric-card blue"><small>Cotizaciones</small><strong>${data.totals.quotations}</strong><span class="kpi-note">Total: ${money(data.totals.total)}</span></article><article class="metric-card purple"><small>Conversión a orden</small><strong>${Number(data.conversion.rate).toFixed(1)}%</strong><span class="kpi-note">${data.conversion.converted} de ${data.conversion.total}</span></article><article class="metric-card amber"><small>Órdenes de servicio</small><strong>${data.totals.orders}</strong><span class="kpi-note">Órdenes no canceladas</span></article><article class="metric-card blue"><small>Visitas técnicas</small><strong>${data.totals.visits}</strong><span class="kpi-note">Dentro del periodo</span></article><article class="metric-card teal"><small>IGV estimado</small><strong>${money(data.totals.igv)}</strong><span class="kpi-note">18% sobre cotizaciones</span></article></div><section class="report-section-grid"><article class="module-card report-card report-supplier-card"><div class="section-heading"><div><h3>Clientes con mayor valor cotizado</h3><p class="muted">Ranking por subtotal de cotizaciones emitidas.</p></div><span class="hero-badge">Top ${data.customers.length}</span></div><div class="report-chart-intro"><span>Cliente</span><strong>Subtotal cotizado</strong></div>${customerBars || '<div class="empty-state">Aún no hay cotizaciones para analizar.</div>'}</article><article class="module-card report-card"><div class="section-heading"><div><h3>Conversión del embudo comercial</h3><p class="muted">No toda cotización termina en una orden de servicio.</p></div></div>${conversionBars}</article></section><section class="report-section-grid"><article class="module-card report-card line-chart-card"><div class="section-heading"><div><h3>Valor cotizado mensual</h3><p class="muted">Histórico y proyección lineal de los próximos tres meses.</p></div></div>${lineChart}</article><article class="module-card report-card status-chart-card"><div class="section-heading"><div><h3>Estado de órdenes de servicio</h3><p class="muted">Carga actual del servicio vendido.</p></div></div>${orderBars || '<div class="empty-state">Aún no hay órdenes de servicio.</div>'}</article></section><section class="report-section-grid"><article class="module-card report-card status-chart-card"><div class="section-heading"><div><h3>Actividad de visitas técnicas</h3><p class="muted">Seguimiento de visitas programadas y realizadas.</p></div></div>${visitBars || '<div class="empty-state">Aún no hay visitas técnicas.</div>'}</article><article class="module-card report-card"><div class="section-heading"><div><h3>Lectura gerencial</h3><p class="muted">Indicadores para priorizar seguimiento comercial.</p></div></div><div class="kpi-definition-grid"><span><strong>Conversión comercial</strong><small>Separa propuestas en evaluación de las que ya originaron una orden.</small></span><span><strong>Valor por cliente</strong><small>Ayuda a enfocar cuentas con mayor potencial económico.</small></span><span><strong>Visitas técnicas</strong><small>Permiten medir actividad de preventa y avance de oportunidades.</small></span></div></article></section>`;
  $('#sales-report-apply').addEventListener('click', () => loadSalesReports({ date_from: $('#sales-report-date-from').value, date_to: $('#sales-report-date-to').value, customer_id: $('#sales-report-customer').value })); $('#sales-report-clear').addEventListener('click', () => loadSalesReports()); bindSalesNav();
}

async function loadSales(section = 'dashboard') {
  $('#page-title').textContent = 'Ventas';
  if (section === 'dashboard') return loadSalesDashboard();
  if (section === 'customers') return loadCustomers();
  if (section === 'quotations') return loadQuotations();
  if (section === 'technical-visits') return loadTechnicalVisits();
  if (section === 'service-orders') return loadServiceOrders();
  if (section === 'reports') return loadSalesReports();
  if (section !== 'dashboard') {
    const item = salesSections.find(([key]) => key === section);
    $('#workspace-content').innerHTML = `${salesNav(section)}<section class="hero"><div><p class="eyebrow">VENTAS / EN DISEÑO</p><h2>${item[1]}</h2><p>${item[2]}</p></div><span class="hero-badge">Planificado</span></section><article class="module-card finance-placeholder"><h3>Sección preparada</h3><p>La navegación está lista. La lógica se implementará sobre entidades propias de Ventas y se enlazará con Finanzas mediante IDs, sin duplicar compañías ni cuentas.</p></article>`;
  }
  bindSalesNav();
}

