const domainNav = (definition, active) => `<nav class="finance-nav">${definition.sections.map(([key, label]) => `<button class="finance-tab ${key === active ? 'active' : ''}" data-domain-section="${key}">${label}</button>`).join('')}</nav>`;

async function loadDomain(moduleKey, section = 'dashboard') {
  const definition = domainDefinitions[moduleKey];
  if (moduleKey === 'hr') return loadHR(section);
  if (moduleKey === 'purchases' && section === 'suppliers') return loadSuppliers();
  if (moduleKey === 'purchases' && ['material-requests', 'service-requests'].includes(section)) return loadPurchaseRequests(section);
  if (moduleKey === 'purchases' && section === 'purchase-orders') return loadPurchaseOrders();
  if (moduleKey === 'purchases' && section === 'purchase-invoices') return loadPurchaseInvoices();
  if (moduleKey === 'purchases' && section === 'reports') return loadPurchaseReports();
  if (moduleKey === 'projects' && section === 'dashboard') return loadProjectsDashboard();
  if (moduleKey === 'projects' && section === 'projects') return loadProjects();
  if (moduleKey === 'projects' && section === 'tasks') return loadTasks();
  if (moduleKey === 'projects' && section === 'gantt') return loadGantt();
  $('#page-title').textContent = definition.title;
  const item = definition.sections.find(([key]) => key === section) || definition.sections[0];
  if (section === 'dashboard') {
    $('#workspace-content').innerHTML = `${domainNav(definition, section)}<section class="hero"><div><p class="eyebrow">${definition.eyebrow}</p><h2>Dashboard</h2><p>${definition.description}</p></div><span class="hero-badge">● En diseño</span></section><div class="card-grid"><article class="metric-card teal"><small>Registros activos</small><strong>0</strong></article><article class="metric-card blue"><small>Procesos en curso</small><strong>0</strong></article><article class="metric-card amber"><small>Pendientes</small><strong>0</strong></article></div><section class="module-grid">${definition.sections.slice(1).map(([key, label, description]) => `<article class="module-card planned"><span class="pill planned">Próximamente</span><h3>${label}</h3><p>${description}</p></article>`).join('')}</section>`;
  } else {
    $('#workspace-content').innerHTML = `${domainNav(definition, section)}<section class="hero"><div><p class="eyebrow">${definition.eyebrow} / EN DISEÑO</p><h2>${item[1]}</h2><p>${item[2]}</p></div><span class="hero-badge">Planificado</span></section><article class="module-card finance-placeholder"><h3>Sección preparada</h3><p>La navegación está lista. Esta capacidad tendrá tablas y reglas propias. Las relaciones previstas se enlazarán con Finanzas, Ventas e Inventario mediante identificadores.</p></article>`;
  }
  document.querySelectorAll('[data-domain-section]').forEach(button => button.addEventListener('click', () => loadDomain(moduleKey, button.dataset.domainSection)));
}

async function loadSettings(section = 'company') {
  $('#page-title').textContent = 'Configuración';
  const [companies, files] = await Promise.all([api('/settings/companies'), api('/settings/data/files')]);
  $('#workspace-content').innerHTML = `<section class="hero"><div><p class="eyebrow">ADMINISTRACIÓN DEL ESPACIO</p><h2>Configuración</h2><p>Define la identidad, seguridad, comunicaciones y archivos de la operación independiente.</p></div><span class="hero-badge">● Admin</span></section><div class="settings-layout"><nav class="settings-nav">${[['company','Compañía'],['users','Usuarios'],['organization','Organización'],['access','Accesos'],['email','Email'],['data','Data']].map(([key,label]) => `<button class="settings-tab ${key === section ? 'active' : ''}" data-settings-section="${key}">${label}</button>`).join('')}</nav><section id="settings-panel" class="settings-panel"></section></div>`;
  document.querySelectorAll('[data-settings-section]').forEach(button => button.addEventListener('click', () => loadSettings(button.dataset.settingsSection)));
  renderSettingsSection(section, companies.companies, files.files);
}

function renderSettingsSection(section, companies, files) {
  const panel = $('#settings-panel');
  if (section === 'company') {
    panel.innerHTML = `<div class="section-heading"><div><h3>Compañía</h3><p class="muted">Administra la razón social, RUC, descripción y moneda. Accounts solo consume esta configuración.</p></div></div><form id="company-create-form" class="compact-form company-create-form"><input name="name" placeholder="Razón social" required><input name="tax_id" placeholder="RUC"><textarea name="description" placeholder="Descripción de la compañía"></textarea><select name="default_currency"><option value="PEN">PEN</option><option value="USD">USD</option><option value="EUR">EUR</option></select><button class="primary" type="submit">Crear compañía</button></form><div class="company-settings-list">${companies.map(company => `<form class="company-settings-card" data-company-form="${company.id}"><div class="section-heading"><h4>Editar compañía #${company.id}</h4><span class="pill ${company.is_active ? 'active' : 'planned'}">${company.is_active ? 'Activa' : 'Inactiva'}</span></div><input name="name" value="${company.name}" placeholder="Razón social" required><input name="tax_id" value="${company.tax_id || ''}" placeholder="RUC"><textarea name="description" placeholder="Descripción">${company.description || ''}</textarea><div class="company-form-footer"><select name="default_currency"><option value="PEN" ${company.default_currency === 'PEN' ? 'selected' : ''}>PEN</option><option value="USD" ${company.default_currency === 'USD' ? 'selected' : ''}>USD</option><option value="EUR" ${company.default_currency === 'EUR' ? 'selected' : ''}>EUR</option></select><button class="primary" type="submit">Guardar cambios</button></div></form>`).join('') || '<p class="muted">Aún no hay compañías configuradas.</p>'}</div>`;
    $('#company-create-form').addEventListener('submit', async event => { event.preventDefault(); try { await api('/settings/companies', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: formData(event.target) }); toast('Compañía creada'); loadSettings('company'); } catch (error) { toast(error.message); } });
    document.querySelectorAll('[data-company-form]').forEach(form => form.addEventListener('submit', async event => { event.preventDefault(); try { await api(`/settings/companies/${form.dataset.companyForm}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: formData(form) }); toast('Compañía actualizada'); loadSettings('company'); } catch (error) { toast(error.message); } }));
    return;
  }
  if (section === 'users') {
    api('/admin/users').then(({ users }) => {
      panel.innerHTML = `<div class="section-heading"><div><h3>Usuarios</h3><p class="muted">Activa cuentas y asigna el módulo que puede utilizar cada persona.</p></div></div><div class="user-table">${users.map(user => `<div class="user-row"><div><strong>${user.username}</strong><small>${user.email}</small></div><select class="role-select" data-settings-user-role="${user.id}"><option value="user" ${user.role === 'user' ? 'selected' : ''}>Usuario</option><option value="accounts" ${user.role === 'accounts' ? 'selected' : ''}>Finanzas</option><option value="selling" ${user.role === 'selling' ? 'selected' : ''}>Ventas</option><option value="hr" ${user.role === 'hr' ? 'selected' : ''}>RR.HH.</option><option value="integrations" ${user.role === 'integrations' ? 'selected' : ''}>Integraciones</option><option value="admin" ${user.role === 'admin' ? 'selected' : ''}>Admin</option></select><label class="active-toggle"><input type="checkbox" data-settings-user-active="${user.id}" ${user.is_active ? 'checked' : ''}> Activo</label></div>`).join('')}</div>`;
      document.querySelectorAll('[data-settings-user-role], [data-settings-user-active]').forEach(control => control.addEventListener('change', async event => { const row = event.target.closest('.user-row'); const id = event.target.dataset.settingsUserRole || event.target.dataset.settingsUserActive; try { await api(`/admin/users/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ role: row.querySelector('[data-settings-user-role]').value, is_active: row.querySelector('[data-settings-user-active]').checked }) }); toast('Usuario actualizado'); } catch (error) { toast(error.message); } }));
    }).catch(error => { panel.innerHTML = `<p class="form-error">${error.message}</p>`; });
    return;
  }
  if (section === 'organization') {
    panel.innerHTML = `<h3>Organización</h3><p class="muted">Aquí definiremos unidades, áreas y responsables. La primera versión mantiene esta estructura separada de las compañías para que una organización pueda operar varias entidades contables.</p><div class="empty-state">Estructura organizativa preparada para la siguiente iteración.</div>`;
    return;
  }
  if (section === 'access') {
    panel.innerHTML = `<h3>Accesos</h3><p class="muted">Los permisos iniciales se asignan por rol. El detalle por módulo se ampliará sin mezclar autorización con identidad.</p><div class="access-grid"><article><strong>admin</strong><small>Configuración completa y administración de usuarios.</small></article><article><strong>accounts</strong><small>Acceso al módulo Finanzas: compañías contables, cuentas, periodos y asientos.</small></article><article><strong>selling</strong><small>Acceso al módulo Ventas: clientes, cotizaciones y órdenes de servicio.</small></article><article><strong>user</strong><small>Acceso básico cuando el administrador lo habilite.</small></article></div>`;
    return;
  }
  if (section === 'email') {
    panel.innerHTML = `<h3>Email</h3><p class="muted">La configuración SMTP se mantendrá propia de la aplicación independiente y no dependerá de Frappe.</p><form class="compact-form settings-form"><input placeholder="Servidor SMTP" disabled><input placeholder="Puerto" disabled><input placeholder="Correo remitente" disabled><button class="primary" type="button" disabled>Guardar configuración</button></form><div class="empty-state">Integración SMTP pendiente de definir credenciales y proveedor.</div>`;
    return;
  }
  panel.innerHTML = `<div class="section-heading"><div><h3>Data</h3><p class="muted">Carga archivos de referencia o intercambio. Formatos permitidos: PDF, CSV y TXT. Tamaño máximo: 25 MB.</p></div></div><form id="data-upload-form" class="upload-form"><input name="file" type="file" accept=".pdf,.csv,.txt,application/pdf,text/csv,text/plain" required><button class="primary" type="submit">Subir archivo</button></form><div class="data-list">${files.map(file => `<div class="data-row"><span><strong>${file.original_name}</strong><small>${file.extension.toUpperCase()} · ${Math.ceil(file.size_bytes / 1024)} KB · ${file.uploaded_by}</small></span><span><a class="link-button" href="/ind-api/settings/data/files/${file.id}" target="_blank">Descargar</a> <button class="link-button" data-delete-file="${file.id}" type="button">Eliminar</button></span></div>`).join('') || '<p class="muted">No hay archivos cargados.</p>'}</div>`;
  $('#data-upload-form').addEventListener('submit', async event => { event.preventDefault(); try { await api('/settings/data/files', { method: 'POST', body: new FormData(event.target) }); toast('Archivo cargado'); loadSettings('data'); } catch (error) { toast(error.message); } });
  document.querySelectorAll('[data-delete-file]').forEach(button => button.addEventListener('click', async event => { if (!window.confirm('¿Eliminar este archivo?')) return; try { await api(`/settings/data/files/${event.target.dataset.deleteFile}`, { method: 'DELETE' }); toast('Archivo eliminado'); loadSettings('data'); } catch (error) { toast(error.message); } }));
}

$('#show-register').addEventListener('click', () => showAuthPanel('register'));
$('#show-login').addEventListener('click', () => showAuthPanel('login'));
$('#login-form').addEventListener('submit', async event => { event.preventDefault(); $('#auth-error').textContent = ''; try { const user = await api('/auth/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: formData(event.target) }); toast('Sesión iniciada'); showApp(user); } catch (error) { showError(error); } });
$('#register-form').addEventListener('submit', async event => { event.preventDefault(); $('#auth-error').textContent = ''; try { await api('/auth/register', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: formData(event.target) }); event.target.reset(); showAuthPanel('login'); toast('Cuenta creada; queda pendiente de activación'); } catch (error) { showError(error); } });
$('#logout').addEventListener('click', async () => { await api('/auth/logout', { method: 'POST' }); location.reload(); });
boot().catch(error => { $('#auth-error').textContent = `No se pudo conectar con el servicio: ${error.message}`; });
